INSERT INTO core_taxonomy (taxonomy_id, rank, name, parent_id)
SELECT
  '1117',
  'phylum',
  'Cyanobacteriota',
  NULL
WHERE NOT EXISTS (
  SELECT 1 FROM core_taxonomy WHERE taxonomy_id='1117'
);

UPDATE core_taxonomy
SET
  rank = COALESCE(NULLIF(rank,''), 'phylum'),
  name = COALESCE(NULLIF(name,''), 'Cyanobacteriota'),
  parent_id = COALESCE(parent_id, NULL)
WHERE taxonomy_id='1117';

