        WHERE genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_005125.1' LIMIT 1)
          AND start=754290 AND end=754303 AND strand=-1
          AND _seq='TGGACAGGTGTTCA'
        ORDER BY site_id DESC LIMIT 1)
        ORDER BY id DESC LIMIT 1),
  (SELECT gene_id FROM core_gene
            WHERE locus_tag='GLL_RS03695' AND genome_id=(SELECT genome_id FROM core_genome WHERE genome_accession='NC_005125.1' LIMIT 1)
